typedef unsigned int size_t;

inline void *operator new(size_t, void *p) { return p; }

extern "C" void *arch_malloc(unsigned int, const char *, int);
extern "C" void arch_free(void *);

template <class T>
class my_allocator {
public:
  static T *allocate(size_t n) {
    return n ? (T *)arch_malloc(n * sizeof(T), __FILE__, 0) : 0;
  }
  static void deallocate(T *p, size_t) {
    if (p) arch_free(p);
  }
};

class stringx {
  char *chars;
  void *my_buf;
public:
  stringx(const stringx&);
  ~stringx();
  stringx& operator=(const stringx&);
};

class timer_widget {
public:
  struct timer_func {
    float time;
    stringx function;
  };
};

template <class T>
inline void construct(T *p, const T& value) { new ((void*)p) T(value); }

template <class T>
inline void destroy(T *p) { p->~T(); }

template <class T>
inline void destroy(T *first, T *last) {
  while (first != last) { destroy(first); ++first; }
}

template <class T>
T *uninitialized_copy(T *first, T *last, T *result) {
  T *cur = result;
  while (first != last) { construct(cur, *first); ++first; ++cur; }
  return cur;
}

template <class T>
T *uninitialized_fill_n(T *first, unsigned int n, const T& value) {
  T *cur = first;
  while (n) { construct(cur, value); ++cur; --n; }
  return cur;
}

template <class T>
T *copy_backward(T *first, T *last, T *result) {
  while (first != last) { --result; --last; *result = *last; }
  return result;
}

template <class T>
void fill(T *first, T *last, const T& value) {
  while (first != last) { *first = value; ++first; }
}

template <class T>
inline const T& max(const T& a, const T& b) { return a < b ? b : a; }

template <class T, class Alloc>
class vector {
protected:
  T *_M_start;
  T *_M_finish;
  T *_M_end_of_storage;
  typedef T *iterator;
  typedef unsigned int size_type;
  T *_M_allocate(size_type n) { return Alloc::allocate(n); }
  void _M_deallocate(T *p, size_type n) { Alloc::deallocate(p, n); }
public:
  size_type size() const { return size_type(_M_finish - _M_start); }
  void insert(iterator position, size_type n, const T& x);
};

template <class T, class Alloc>
void vector<T, Alloc>::insert(iterator position, size_type n, const T& x)
{
  if (n != 0) {
    if (size_type(_M_end_of_storage - _M_finish) >= n) {
      T x_copy = x;
      const size_type elems_after = _M_finish - position;
      iterator old_finish = _M_finish;
      if (elems_after > n) {
        uninitialized_copy(_M_finish - n, _M_finish, _M_finish);
        _M_finish += n;
        copy_backward(position, old_finish - n, old_finish);
        fill(position, position + n, x_copy);
      }
      else {
        uninitialized_fill_n(_M_finish, n - elems_after, x_copy);
        _M_finish += n - elems_after;
        uninitialized_copy(position, old_finish, _M_finish);
        _M_finish += elems_after;
        fill(position, old_finish, x_copy);
      }
    }
    else {
      const size_type old_size = size();
      const size_type len = old_size + max(old_size, n);
      iterator new_start = _M_allocate(len);
      iterator new_finish = new_start;
      new_finish = uninitialized_copy(_M_start, position, new_start);
      new_finish = uninitialized_fill_n(new_finish, n, x);
      new_finish = uninitialized_copy(position, _M_finish, new_finish);
      destroy(_M_start, _M_finish);
      _M_deallocate(_M_start, _M_end_of_storage - _M_start);
      _M_start = new_start;
      _M_finish = new_finish;
      _M_end_of_storage = new_start + len;
    }
  }
}

template void vector<timer_widget::timer_func, my_allocator<timer_widget::timer_func> >::insert(timer_widget::timer_func *, unsigned int, const timer_widget::timer_func&);
